<?php
$pageTitle='Outside Car Workspace';
$pageIcon='<i class="ri-car-line"></i>';
require_once __DIR__.'/../includes/header.php';
require_once __DIR__.'/../includes/accounting_engine.php';
require_once __DIR__.'/../includes/attachments.php';
$businessId=Auth::user('business_id');
Auth::requireBookAccess('outside_cars','read');
$engine=new AccountingEngine($businessId,Auth::user('user_id'));
$carId=trim((string)get('id',''));
$ownership=$db->fetch("SELECT ownership_type FROM cars WHERE id=? AND business_id=?",[$carId,$businessId]);
if(!$ownership){setFlash('error','Car not found.');redirect('index.php');}
if($ownership['ownership_type']==='COMMISSION')redirect('../cars/commission_view.php?id='.urlencode($carId));
if($ownership['ownership_type']!=='OUTSIDE'){setFlash('error','This is not an Outside Car.');redirect('../cars/view.php?id='.urlencode($carId));}
$canWrite=Auth::hasBookAccess('outside_cars','write');
$groups=Auth::getAccessiblePrimaryAccountList($businessId,'write');
$accounts=array_merge($groups['cash_book']??[],$groups['bank_book']??[]);
$accountIds=array_column($accounts,'id');
$buyers=$db->fetchAll("SELECT id,name,phone FROM debtors_creditors WHERE business_id=? AND is_active=1 AND type IN ('BUYER','DEBTOR') ORDER BY name",[$businessId]);
$actionError='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verifyCsrf();
    $action=post('action');
    try{
        if(!$canWrite)throw new Exception('Outside Cars write permission is required.');
        $accountAction=in_array($action,['advance','expense','sale','buyer_payment','buyer_refund','entity_payment','rto'],true);
        $selectedAccount=post($action==='sale'?'receiving_account':($action==='expense'?'payment_account':'account_id'));
        if($accountAction && !($action==='sale' && parseDecimalInput(post('amount_received_now'))<=0) && !in_array($selectedAccount,$accountIds,true)) throw new Exception('Select an accessible Cash or Bank account.');
        if($action==='advance')$engine->recordOutsideEntityAdvance($carId,parseDecimalInput(post('amount')),post('entry_date'),post('account_id'),post('direction'),post('narration'));
        elseif($action==='expense')$engine->recordOutsideCarExpense($carId,['amount'=>parseDecimalInput(post('amount')),'approved_recoverable_amount'=>parseDecimalInput(post('approved_recoverable_amount')),'expense_date'=>post('expense_date'),'category'=>post('category'),'vendor_name'=>post('vendor_name'),'responsibility'=>post('responsibility'),'difference_bearer'=>post('difference_bearer'),'payment_account'=>post('payment_account'),'narration'=>post('narration')]);
        elseif($action==='sale')$engine->recordOutsideCarSale($carId,['sale_date'=>post('sale_date'),'vehicle_sale_price'=>parseDecimalInput(post('vehicle_sale_price')),'discount_amount'=>parseDecimalInput(post('discount_amount')),'separate_commission'=>post('separate_commission'),'buyer_rto_charge'=>parseDecimalInput(post('buyer_rto_charge')),'other_buyer_charges'=>parseDecimalInput(post('other_buyer_charges')),'buyer_party_id'=>post('buyer_party_id'),'buyer_name'=>post('new_buyer_name'),'buyer_phone'=>post('new_buyer_phone'),'amount_received_now'=>post('amount_received_now'),'receiving_account'=>post('receiving_account'),'narration'=>post('narration')]);
        elseif($action==='buyer_payment')$engine->recordOutsideBuyerPayment($carId,parseDecimalInput(post('amount')),post('payment_date'),post('account_id'),post('narration'));
        elseif($action==='buyer_refund')$engine->recordOutsideBuyerRefund($carId,parseDecimalInput(post('amount')),post('payment_date'),post('account_id'),post('narration'));
        elseif($action==='settlement')$engine->approveOutsideCarSettlement($carId,['settlement_date'=>post('settlement_date'),'approved_margin'=>post('approved_margin'),'difference_target'=>post('difference_target'),'approval_reason'=>post('approval_reason')]);
        elseif($action==='entity_payment')$engine->payOutsideEntity($carId,parseDecimalInput(post('amount')),post('payment_date'),post('account_id'),post('narration'));
        elseif($action==='rto')$engine->recordOutsideRtoMovement($carId,post('movement_type'),parseDecimalInput(post('amount')),post('movement_date'),post('account_id'),post('narration'));
        elseif($action==='rto_shortfall')$engine->recordOutsideRtoShortfall($carId,parseDecimalInput(post('amount')),post('bearer'),post('movement_date'),post('narration'));
        elseif($action==='complete_rto')$engine->completeOutsideRto($carId,post('completion_reason'));
        elseif($action==='agreement'){$engine->generateOutsideCarAgreement($carId,['buyer_address'=>post('buyer_address'),'delivery_terms'=>post('delivery_terms'),'witness_1'=>post('witness_1'),'witness_2'=>post('witness_2')]);}
        elseif($action==='sign_agreement'){
            $agreementId=post('agreement_id');
            $count=uploadEntityAttachments($businessId,'OUTSIDE_CAR_AGREEMENT',$agreementId,'SIGNED_COPY','signed_files',Auth::user('user_id'),'documents');
            if($count<1)throw new Exception('Attach at least one signed scan or photo.');
            $engine->markOutsideCarAgreementSigned($agreementId);
        }
        elseif($action==='delivery')$engine->recordOutsideCarDelivery($carId,['delivery_date'=>post('delivery_date'),'delivery_time'=>post('delivery_time'),'odometer'=>post('odometer'),'fuel_level'=>post('fuel_level'),'keys_handed_over'=>post('keys_handed_over'),'documents_handed_over'=>post('documents_handed_over'),'receiver_name'=>post('receiver_name'),'override_used'=>post('override_used')==='1','override_reason'=>post('override_reason'),'promised_payment_date'=>post('promised_payment_date')]);
        else throw new Exception('Unknown Outside Car action.');
        setFlash('success','Outside Car record updated and linked accounting/audit history saved.');redirect('view.php?id='.urlencode($carId).'#'.urlencode($action));
    }catch(Throwable $e){$actionError=$e->getMessage();}
}
$f=$engine->getOutsideCarFinancials($carId);$car=$f['car'];$sale=$f['sale'];$settlement=$f['settlement'];
$expenses=$db->fetchAll("SELECT oce.*,je.reference_no,u.full_name created_by_name FROM outside_car_expenses oce LEFT JOIN journal_entries je ON je.id=oce.journal_entry_id LEFT JOIN users u ON u.id=oce.created_by AND u.business_id=oce.business_id WHERE oce.business_id=? AND oce.car_id=? ORDER BY oce.expense_date,oce.created_at",[$businessId,$carId]);
$advances=$db->fetchAll("SELECT oca.*,je.reference_no,u.full_name created_by_name FROM outside_car_advances oca LEFT JOIN journal_entries je ON je.id=oca.journal_entry_id LEFT JOIN users u ON u.id=oca.created_by AND u.business_id=oca.business_id WHERE oca.business_id=? AND oca.car_id=? ORDER BY oca.entry_date,oca.created_at",[$businessId,$carId]);
$buyerPayments=$db->fetchAll("SELECT p.*,je.reference_no,u.full_name created_by_name FROM outside_car_buyer_payments p LEFT JOIN journal_entries je ON je.id=p.journal_entry_id LEFT JOIN users u ON u.id=p.created_by AND u.business_id=p.business_id WHERE p.business_id=? AND p.car_id=? ORDER BY p.payment_date,p.created_at",[$businessId,$carId]);
$entityPayments=$db->fetchAll("SELECT p.*,je.reference_no,u.full_name created_by_name FROM outside_entity_payments p LEFT JOIN journal_entries je ON je.id=p.journal_entry_id LEFT JOIN users u ON u.id=p.created_by AND u.business_id=p.business_id WHERE p.business_id=? AND p.car_id=? ORDER BY p.payment_date,p.created_at",[$businessId,$carId]);
$rtoMoves=$db->fetchAll("SELECT r.*,je.reference_no,u.full_name created_by_name FROM outside_car_rto_movements r LEFT JOIN journal_entries je ON je.id=r.journal_entry_id LEFT JOIN users u ON u.id=r.created_by AND u.business_id=r.business_id WHERE r.business_id=? AND r.car_id=? ORDER BY r.movement_date,r.created_at",[$businessId,$carId]);
$agreements=$db->fetchAll("SELECT a.*,u.full_name created_by_name FROM outside_car_agreements a LEFT JOIN users u ON u.id=a.created_by AND u.business_id=a.business_id WHERE a.business_id=? AND a.car_id=? ORDER BY a.version_no DESC",[$businessId,$carId]);
$delivery=$db->fetch("SELECT d.*,u.full_name recorded_by_name FROM outside_car_deliveries d LEFT JOIN users u ON u.id=d.recorded_by AND u.business_id=d.business_id WHERE d.business_id=? AND d.car_id=?",[$businessId,$carId]);
$entries=$db->fetchAll("SELECT je.id,je.reference_no,je.entry_date,je.created_at,je.narration,je.transaction_type,je.entry_type_id,je.entry_amount,je.status,je.is_reversal,u.full_name created_by_name FROM journal_entries je LEFT JOIN users u ON u.id=je.created_by AND u.business_id=je.business_id WHERE je.business_id=? AND je.car_id=? ORDER BY je.entry_date DESC,je.created_at DESC",[$businessId,$carId]);
$settlementApprover=$settlement?$db->fetch("SELECT full_name FROM users WHERE id=? AND business_id=?",[$settlement['approved_by'],$businessId]):null;
$exactMargin=$sale?round(floatval($sale['net_vehicle_value'])-floatval($car['source_base_value'])-floatval($f['expense']['approved']??0),2):0;
$defaultTirangaShare=round($exactMargin*floatval($exactMargin>=0?$car['tiranga_profit_pct']:$car['tiranga_loss_pct'])/100,2);
$commissionInputValue=$car['commission_type']==='FIXED'?floatval($car['commission_value']):'';
$commissionHint=$car['commission_type']==='PERCENT'?'Leave blank to calculate '.clean($car['commission_value']).'% of C automatically.':'Leave blank to use the agreed K amount.';
$buyerNetPaid=$sale?round(floatval($sale['buyer_total'])-floatval($sale['buyer_outstanding']),2):0;
$latestAgreement=$agreements[0]??null;
?>
<div class="page-header"><div><h1><i class="ri-car-line"></i> <?= clean(formatRegistrationNo($car['registration_no'])) ?></h1><p class="page-subtitle"><?= clean(trim($car['make'].' '.$car['model'])) ?> · Source Entity: <a href="../parties/view.php?id=<?= urlencode($car['source_party_id']) ?>"><?= clean($car['source_entity_name']) ?></a></p></div><div class="page-actions"><?php if($sale): ?><a href="../cars/loan_commission.php?car_id=<?= urlencode($carId) ?>" class="btn btn-outline"><i class="ri-bank-card-line"></i> Loan Commission</a><?php endif; ?><a href="sheet.php?id=<?= urlencode($carId) ?>" class="btn btn-outline"><i class="ri-printer-line"></i> A/B/C/K Sheet</a><a href="index.php" class="btn btn-outline"><i class="ri-arrow-left-line"></i> Back</a></div></div>
<?php if($actionError): ?><div class="alert alert-error"><i class="ri-error-warning-line"></i> <?= clean($actionError) ?></div><?php endif; ?>
<div class="outside-status-strip"><span><b>Physical</b> <?= clean(str_replace('_',' ',$car['physical_status'])) ?></span><span><b>Buyer</b> <?= clean(str_replace('_',' ',$car['buyer_status'])) ?></span><span><b>RTO</b> <?= clean(str_replace('_',' ',$car['rto_status'])) ?></span><span><b>Settlement</b> <?= clean(str_replace('_',' ',$car['settlement_status'])) ?></span><span><b>Agreement</b> <?= clean(str_replace('_',' ',$car['agreement_status'])) ?></span></div>
<nav class="outside-workspace-nav" aria-label="Outside Car sections"><?php foreach(['overview'=>'Overview','buyer'=>'Buyer & Payments','expenses'=>'Expenses','settlement'=>'Settlement','source'=>'Source Entity','rto'=>'RTO','agreement'=>'Agreement','delivery'=>'Delivery','audit'=>'Audit'] as $anchor=>$label): ?><a href="#<?= $anchor ?>"><?= clean($label) ?></a><?php endforeach; ?></nav>

<section id="overview" class="card"><div class="card-header"><h3><i class="ri-dashboard-line"></i> Overview</h3></div><div class="card-body"><div class="outside-abck-grid">
<a href="#source"><b>A</b><span>Source Base Value</span><strong><?= formatAmount($car['source_base_value']) ?></strong></a><a href="#expenses"><b>B1</b><span>Actual Expenses</span><strong><?= formatAmount($f['expense']['actual']??0) ?></strong></a><a href="#expenses"><b>B2</b><span>Approved Recoverable</span><strong><?= formatAmount($f['expense']['approved']??0) ?></strong></a><a href="#buyer"><b>C</b><span>Vehicle Selling Price</span><strong><?= $sale?formatAmount($sale['vehicle_sale_price']):'Pending' ?></strong></a><a href="#buyer"><b>K</b><span>Separate Commission</span><strong><?= $sale?formatAmount($sale['separate_commission']):($car['commission_type']==='PERCENT'?clean($car['commission_value']).'%':formatAmount($car['commission_value'])) ?></strong></a></div>
<?php if($sale): ?><div class="stats-grid outside-calc-stats"><div class="stat-card"><div class="stat-value"><?= formatAmount($exactMargin) ?></div><div class="stat-label">Exact Margin: C − A − B2</div></div><div class="stat-card"><div class="stat-value flow-in"><?= formatAmount($defaultTirangaShare) ?></div><div class="stat-label">Calculated Tiranga Share</div></div><div class="stat-card"><div class="stat-value flow-in"><?= formatAmount(($f['expense']['approved']??0)+$defaultTirangaShare+floatval($sale['separate_commission'])) ?></div><div class="stat-label">Tiranga Settlement Entitlement</div></div></div><?php endif; ?>
</div></section>

