bel><input name="amount_received_now" class="form-control currency-input" value="0"></div><div class="form-group"><label class="form-label">Receive Into</label><select name="receiving_account" class="form-control searchable-select"><option value="">Required only when receiving now</option><?php foreach($accounts as $account): ?><option value="<?= clean($account['id']) ?>"><?= clean($account['name']) ?></option><?php endforeach; ?></select></div></div><input name="narration" class="form-control" value="Outside Car sale - <?= clean($car['registration_no']) ?>"><button class="btn btn-primary" style="margin-top:12px"><i class="ri-money-rupee-circle-line"></i> Record Buyer Sale</button></form>
