count): ?><option value="<?= clean($account['id']) ?>"><?= clean($account['name']) ?></option><?php endforeach; ?></select></div></div><input name="narration" class="form-control" placeholder="Reason and reference"><button class="btn btn-primary" style="margin-top:12px">Record Classified Expense</button></form><?php endif; ?>
